/* QR18-02-B: export the authorized, filtered equipment list using the original eight-column form. */
(()=>{
const words={mapping:['QR18-02 設備登錄表','QR18-02 Equipment Registration Form','QR18-02 Formulario de registro de equipo','QR18-02 Phiếu đăng ký thiết bị'],erTitle:['設備登錄表','Equipment Registration Form','Formulario de registro de equipo','Phiếu đăng ký thiết bị'],erUnit:['使用單位','Using department','Departamento de uso','Bộ phận sử dụng'],erItem:['項次','Item','Ítem','STT'],erCategory:['設備類別','Equipment Category','Categoría de equipo','Loại thiết bị'],erNumber:['設備編號','Equipment Number','Número de equipo','Mã thiết bị'],erProperty:['財產編號','Property Number','Número de propiedad','Mã tài sản'],erName:['設備名稱','Equipment Name','Nombre de equipo','Tên thiết bị'],erRegistrar:['登錄人','Registrar','Persona que registra','Người đăng ký'],erDate:['登錄日期','Registration Date','Fecha de registro','Ngày đăng ký'],erNote:['備註','Note','Nota','Ghi chú'],erExport:['匯出設備登錄表 (Excel)','Export registration form (Excel)','Exportar registro (Excel)','Xuất phiếu đăng ký (Excel)'],erPrint:['列印設備登錄表','Print registration form','Imprimir registro','In phiếu đăng ký'],erPreview:['設備登錄表預覽','Registration form preview','Vista previa del registro','Xem trước phiếu đăng ký'],erTemplate:['下載設備匯入範本','Download equipment import template','Descargar plantilla de importación','Tải mẫu nhập thiết bị'],erHelp:['依目前部門與設備群組篩選匯出；各使用單位分開成表。登錄人、登錄日期與備註尚無資料時留白，可於 Excel 補填。列印每頁右下角顯示 QR18-02-B。','Export the current department and equipment-group filters, with one form per department. Missing registrar, registration date and notes remain blank for entry in Excel. Each printed page shows QR18-02-B at bottom right.','Exporta los filtros actuales, con un formulario por departamento. Registrador, fecha y notas sin datos quedan vacíos para completar en Excel. Cada página lleva QR18-02-B abajo a la derecha.','Xuất theo bộ phận và nhóm thiết bị đang lọc, mỗi bộ phận một phiếu. Người đăng ký, ngày và ghi chú chưa có dữ liệu được để trống để điền trong Excel. Mỗi trang in có QR18-02-B ở góc dưới bên phải.']};
for(const[k,v]of Object.entries(words))translations[k]=Object.fromEntries(['zh','en','es','vi'].map((l,i)=>[l,v[i]]));
const headings=['erItem','erCategory','erNumber','erProperty','erName','erRegistrar','erDate','erNote'];
const widths=[6.375,12.125,12.375,14.75,18.25,12.25,12,13];
const label=k=>[translations[k][primary]||translations[k].zh,...(secondary&&secondary!==primary&&translations[k][secondary]?[translations[k][secondary]]:[])].join('\n');
const value=x=>String(x??'').replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g,'').replace(/天車/g,'固定式起重機');
const xml=x=>value(x).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
function formName(row){if(!row)return '';const names=NAME_TRANSLATIONS[row.name_zh]||Object.fromEntries(['zh','en','es','vi'].map(l=>[l,row['name_'+l]||'']));const main=names[primary]||names.zh||row.equipment_name||'';const sub=secondary&&secondary!==primary?names[secondary]:'';return value(main+(sub&&sub!==main?'\n'+sub:''));}
function sections(){const map=new Map();for(const e of filteredEquipment()){if(!map.has(e.department_id))map.set(e.department_id,{name:formName(data.departments.find(d=>d.id===e.department_id)),rows:[]});const s=map.get(e.department_id);s.rows.push([s.rows.length+1,e.equipment_groups?formName(e.equipment_groups):'',e.machine_no||e.equipment_code||'',e.property_no||'',formName(e),e.registered_by||'',e.registration_date||'',e.registration_note||'']);}if(!map.size)map.set(department,{name:formName(data.departments.find(d=>d.id===department))||'',rows:[]});return [...map.values()];}
function papers(){return sections().flatMap(s=>Array.from({length:Math.max(1,Math.ceil(s.rows.length/20))},(_,page)=>{const rows=s.rows.slice(page*20,(page+1)*20);return `<article class="er-paper"><header><h2>${xml(label('erTitle')).replace(/\n/g,'<br>')}</h2></header><p class="er-unit">${xml(label('erUnit')).replace(/\n/g,' / ')}：${xml(s.name)}</p><table><colgroup>${widths.map(w=>`<col style="width:${w/101.125*100}%">`).join('')}</colgroup><thead><tr>${headings.map(k=>`<th>${xml(label(k)).replace(/\n/g,'<br>')}</th>`).join('')}</tr></thead><tbody>${[...rows,...Array.from({length:20-rows.length},()=>Array(8).fill(''))].map(r=>`<tr>${r.map(v=>`<td>${xml(v)}</td>`).join('')}</tr>`).join('')}</tbody></table><footer>QR18-02-B</footer></article>`;})).join('');}
function print(){const node=document.createElement('div');node.id='equipmentRegistrationPrint';node.innerHTML=papers()+'<div class="er-print-footer">QR18-02-B</div>';document.body.append(node);document.body.classList.add('printing-registration');try{window.print();}finally{document.body.classList.remove('printing-registration');node.remove();}}
const declaration='<?xml version="1.0" encoding="UTF-8" standalone="yes"?>';
const ns='http://schemas.openxmlformats.org/spreadsheetml/2006/main';
function cell(v,r,c,style){const ref=String.fromCharCode(65+c)+r;return typeof v==='number'?`<c r="${ref}" s="${style}"><v>${v}</v></c>`:`<c r="${ref}" s="${style}" t="inlineStr"><is><t xml:space="preserve">${xml(v)}</t></is></c>`;}
function sheetXml(s){const rows=[{v:[label('erTitle'),...Array(7).fill('')],h:70,style:1},{v:[label('erUnit').replace(/\n/g,' / ')+'：'+s.name,...Array(7).fill('')],h:30,style:2},{v:headings.map(label),h:65,style:3},...s.rows.map(v=>({v,h:25,style:4})),...Array.from({length:Math.max(0,20-s.rows.length)},()=>({v:Array(8).fill(''),h:25,style:4}))];const last=rows.length;return declaration+`<worksheet xmlns="${ns}"><sheetPr><pageSetUpPr fitToPage="1"/></sheetPr><dimension ref="A1:H${last}"/><sheetViews><sheetView workbookViewId="0" showGridLines="0"><pane ySplit="3" topLeftCell="A4" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><sheetFormatPr defaultRowHeight="25"/><cols>${widths.map((w,i)=>`<col min="${i+1}" max="${i+1}" width="${w}" customWidth="1"/>`).join('')}</cols><sheetData>${rows.map((r,i)=>`<row r="${i+1}" ht="${r.h}" customHeight="1">${r.v.map((v,c)=>cell(v,i+1,c,r.style)).join('')}</row>`).join('')}</sheetData><mergeCells count="2"><mergeCell ref="A1:H1"/><mergeCell ref="A2:H2"/></mergeCells><printOptions horizontalCentered="1"/><pageMargins left="0.315" right="0.315" top="0.5" bottom="0.5" header="0.2" footer="0.2"/><pageSetup paperSize="9" orientation="portrait" fitToWidth="1" fitToHeight="0"/><headerFooter><oddFooter>&amp;RQR18-02-B</oddFooter></headerFooter></worksheet>`;}
const styles=declaration+`<styleSheet xmlns="${ns}"><fonts count="3"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="18"/><name val="Calibri"/></font><font><b/><sz val="11"/><name val="Calibri"/></font></fonts><fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills><borders count="2"><border/><border><left style="thin"><color rgb="FF000000"/></left><right style="thin"><color rgb="FF000000"/></right><top style="thin"><color rgb="FF000000"/></top><bottom style="thin"><color rgb="FF000000"/></bottom></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="5"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment horizontal="center" vertical="center" wrapText="1"/></xf><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment horizontal="left" vertical="center" wrapText="1"/></xf><xf numFmtId="0" fontId="2" fillId="0" borderId="1" xfId="0" applyAlignment="1"><alignment horizontal="center" vertical="center" wrapText="1"/></xf><xf numFmtId="49" fontId="0" fillId="0" borderId="1" xfId="0" applyAlignment="1" applyNumberFormat="1"><alignment horizontal="center" vertical="center" wrapText="1"/></xf></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>`;
async function exportExcel(){if(typeof JSZip==='undefined'){toast('exportFailed');return;}const b=$('#mappingExport');if(b)b.disabled=true;try{const zip=new JSZip(),ss=sections(),names=new Set();const sheets=ss.map((s,i)=>{let base=value(s.name).replace(/[\\/*?:\[\]]/g,' ').trim().slice(0,25)||'設備登錄表',name=base;let n=2;while(names.has(name))name=base+' '+n++;names.add(name);return {...s,name,i};});
zip.file('[Content_Types].xml',declaration+`<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>${sheets.map(s=>`<Override PartName="/xl/worksheets/sheet${s.i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}</Types>`);
zip.file('_rels/.rels',declaration+'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');
zip.file('xl/workbook.xml',declaration+`<workbook xmlns="${ns}" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><bookViews><workbookView/></bookViews><sheets>${sheets.map(s=>`<sheet name="${xml(s.name)}" sheetId="${s.i+1}" r:id="rId${s.i+1}"/>`).join('')}</sheets><definedNames>${sheets.map(s=>`<definedName name="_xlnm.Print_Titles" localSheetId="${s.i}">'${xml(s.name.replace(/'/g,"''"))}'!$1:$3</definedName><definedName name="_xlnm.Print_Area" localSheetId="${s.i}">'${xml(s.name.replace(/'/g,"''"))}'!$A$1:$H$${Math.max(20,s.rows.length)+3}</definedName>`).join('')}</definedNames></workbook>`);
zip.file('xl/_rels/workbook.xml.rels',declaration+`<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${sheets.map(s=>`<Relationship Id="rId${s.i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${s.i+1}.xml"/>`).join('')}<Relationship Id="rIdStyles" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`);zip.file('xl/styles.xml',styles);for(const s of sheets)zip.file(`xl/worksheets/sheet${s.i+1}.xml`,sheetXml(s));const blob=await zip.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',compression:'DEFLATE'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='QR18-02-B 設備登錄表.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}catch{toast('exportFailed');}finally{if(b?.isConnected)b.disabled=false;}}
const previous=renderMapping;renderMapping=function(){previous();$('#mappingExport').innerHTML=txt('erExport');$('#mappingExport').onclick=exportExcel;$('#mappingDownload').innerHTML=txt('erTemplate');$('#mappingExport').insertAdjacentHTML('afterend',button('erPrint','id="mappingPrint"'));$('#mappingPrint').onclick=print;$('#content').insertAdjacentHTML('beforeend',`<p class="notice">${txt('erHelp')}</p><details class="er-preview"><summary>${txt('erPreview')}</summary><div class="er-scroll">${papers()}</div></details>`);};
})();
